function grantLabBuilder(meta,actors){
  const attributes={},steps=[],prefix='grant'+meta.id.replace(/^lab-/,'').split('-').map(s=>s[0].toUpperCase()+s.slice(1)).join('');
  const add=(suffix,name,meaning,origin,purpose,example,standard=meta.protocol==='oidc'?'OpenID CIBA Core 1.0':'RFC 8693',source=meta.source)=>{const id=prefix+suffix;attributes[id]=labAttribute(name,meaning,origin,purpose,example,standard,source);return id;};
  const value=(id,name)=>labP(name||attributes[id].name,attributes[id].example,undefined,id);
  const stage=(key,title,from,to,summary,detail,operations,payload=[],checks=[],channel=from===to?'internal':'backchannel',phase='tokens')=>{const step=labStep(meta.id+'-'+key,title,from,to,phase,channel,summary,detail,[...new Set(operations.map(o=>o.attributeId))],payload,checks,operations);step.labGrantStage=key;steps.push(step);return step;};
  const finish=()=>{const used=new Set(steps.flatMap(s=>s.fields));for(const id of Object.keys(attributes))if(!used.has(id))delete attributes[id];Object.assign(GRANTLAB_ATTRIBUTES,attributes);return labScenario({...meta,architecture:'web'},attributes,steps,actors);};
  return {meta,attributes,steps,add,value,stage,finish};
}
